mapper.select:
WITH RECURSIVE dependent_versions (version_id) AS (
SELECT id FROM resource_version WHERE enterprise_id = #{enterprise} AND resource_id = #{id}
UNION DISTINCT
SELECT d.parent_version_id FROM resource_dependency d JOIN dependent_versions v ON v.version_id =
d.dependency_version_id
WHERE d.enterprise_id = #{enterprise}
)
SELECT COUNT(*) FROM scheduled_task s JOIN dependent_versions v ON v.version_id = s.agent_version_id
WHERE s.enterprise_id = #{enterprise} AND s.enabled = TRUE AND s.deleted_at IS NULL

SELECT COUNT(*) FROM agent_run WHERE enterprise_id = #{enterprise} AND status IN
('queued','running','waiting_approval','cancelling')
AND (JSON_UNQUOTE(JSON_EXTRACT(execution_config_json, '$.agentId')) = #{id}
OR JSON_UNQUOTE(JSON_EXTRACT(execution_config_json, '$.workflowId')) = #{id}
OR JSON_CONTAINS(JSON_EXTRACT(execution_config_json, '$.dependencies'), JSON_OBJECT('resourceId', #{id})))

WITH RECURSIVE dependent_versions (version_id) AS (
SELECT id FROM resource_version WHERE enterprise_id = #{enterprise} AND resource_id = #{id}
UNION DISTINCT
SELECT d.parent_version_id FROM resource_dependency d JOIN dependent_versions v ON v.version_id =
d.dependency_version_id
WHERE d.enterprise_id = #{enterprise}
)
SELECT s.id FROM scheduled_task s JOIN dependent_versions v ON v.version_id = s.agent_version_id
WHERE s.enterprise_id = #{enterprise} AND s.enabled = TRUE AND s.deleted_at IS NULL
